// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems, Neuron} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    Neuron neuron;

    function setUp() public {
        c = new GameItems(address(this), address(this));
        neuron = new Neuron(address(this), address(this), address(this));
        c.instantiateNeuronContract(address(neuron));
        neuron.addSpender(address(c));
        c.createGameItem("item", "uri", false, true, type(uint256).max, 0, type(uint16).max);
    }

    function testFuzz_property(uint256 quantity, address actor) public {
        vm.assume(actor != address(0));
        quantity = bound(quantity, 1, type(uint16).max);

        vm.prank(actor);
        c.mint(0, quantity);

        assertTrue(c.balanceOf(actor, 0) == quantity);
    }
}
